512	
513		// 再改列表项中的回执，正式交换仍不变。
514		lst[0].Receipt.Outcome = ReceiptAccepted
515		lst[0].Receipt.Reason = "列表里本地改的原因"
516		g3, _ := f.s.GetExchange(doc, f.pid, x.ID)
